import React, { useEffect, useMemo } from "react";
import { Store, PageContext, Canvas, Content, Setting, Menu } from "@/components/CustomPage";
import styles from './index.module.less';
import { IconSave } from "@arco-design/web-react/icon";
import { moduleStore } from "react-converter-code";
import module from "@/store/module";
import ajax from "@/utils/ajax";
import { ResizeBox, Button, Message } from "@arco-design/web-react";
import * as H from 'history';


interface PageDesignProps {
    store: Store;
    history: H.History;
}
const PageDesign = ({ store, history }: PageDesignProps) => {
    


    return (
        <div className={styles.component}>
            <PageContext.Provider value={{ store: store.contentData as any }}>
                <ResizeBox.SplitGroup
                    direction='horizontal'
                    style={{ flex: 1, width: "100%" }}
                    panes={[
                        {
                            content: (
                                <Canvas scale={100}
                                    store={store}
                                    onClick={(e) => {
                                        store.setSelectId('')
                                        e.stopPropagation();
                                    }}
                                >
                                    <Content store={store} />
                                </Canvas>
                            ),
                        },
                        {
                            content: (
                                <Setting
                                    pageStore={store}
                                    store={store.settingStore}
                                    onModuleCode={(module) => {
                                        console.log('useHistory', history)
                                        if(module.isPublic){
                                            Message.success("当前为公共模块，如果你要修改，请先保存页面");
                                        }else {
                                            history.push(`/module/save?moduleId=${module.key}`)
                                        }
                                    }}
                                />
                            ),
                            min: "100px",
                            size: '280px'
                        }
                    ]}
                />
            </PageContext.Provider>
        </div>
    )
}

export default PageDesign;